import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';


export type GreenTrendingCounterProps = Record<string, any>;

const GreenTrendingCounter: React.FC<GreenTrendingCounterProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  targetNumber = 500,
  primaryColor = "#f97316", // Orange-500
  secondaryColor = "#ec4899", // Pink-500
  fontSize = 200,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // 1. Counter Animation
  // Counts up over 60% of the duration or 2 seconds, whichever is shorter/smoother
  const countDurationFrames = Math.min(fps * 2, durationInSeconds * fps * 0.6);
  
  const currentCount = Math.floor(
    interpolate(frame, [0, countDurationFrames], [0, targetNumber], {
      extrapolateRight: "clamp",
    })
  );

  // Format number with commas
  const formattedCount = currentCount.toLocaleString();

  // Scale relative to canvas reference (1080px base)
  const s = Math.min(width, height) / 1080;

  // Layout calculations
  const textStyle: React.CSSProperties = {
    fontFamily: '"Helvetica Neue", Helvetica, Arial, sans-serif',
    fontWeight: "bold",
    fontSize: `${fontSize * s}px`,
    background: `linear-gradient(135deg, ${primaryColor}, ${secondaryColor})`,
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    backgroundClip: "text",
    lineHeight: 1.2,
    fontVariantNumeric: "tabular-nums", // Keeps numbers monospaced to prevent jitter
    letterSpacing: "-0.05em",
    textAlign: "center",
    display: "inline-block",
    padding: `0 ${20 * s}px`,
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Number Display with "$" and "K" */}
      <div style={textStyle}>
        ${formattedCount}K
      </div>
    </AbsoluteFill>
  );
};

export default GreenTrendingCounter;